window.RP_SESSION={"id":"S-e1d64ff4bc66","messages":[{"id":"RP-0159478","time":"2026-05-18T22:41:00+09:00","room":"RP","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사촌오빠 님드 앗질랄 아스사피 빈 칼리드 알 쿠라이시에게.\n사촌동생 와르다 알리야 빈 살만 알 쿠라이시가.","characters":["P-f310b84f8f20"]},{"id":"RP-0159479","time":"2026-05-18T22:50:00+09:00","room":"RP","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오빠. 우리 스카일라 안에서나 대상단이지 대륙 스케일로 돈 쓰기 시작하면 답 없으니까 돈 좀 아껴 써. 오빠가 지난달에 상단 앞에 청구한 돈이 얼마인지 알아? 이러다 오빠가 지금까지 모아둔 돈도 바닥나겠어. 뭘 하느라 그렇게 돈을 많이 쓰는거야? 설마 벌어들이는 것 없이 쓰기만 하는 건 아니겠지? 자주 들르겠다더니 집에는 왜 또 한 번을  안 들어와? 아무리 우리 고향이 그렇게 됐다고는 해도 집에 한 번은 들어와야지. 오빠 얼굴은 어차피 다들 어릴 때 이후로 다들 본 적 없다고 쳐도 난 동생인데 갑옷이 어떻게 생겼는지까지 까먹을 정도로 나가만 있는건 너무한거 아니야? 간만에 보내는 편지가 잔소리 밖에 없어서 미안해. 사랑하는거 알지?\n-추신. 남편도 오빠 보고 싶어 한다고 전해달래.","characters":["P-f310b84f8f20"]},{"id":"RP-0159480","time":"2026-05-18T22:51:00+09:00","room":"RP","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"님드는 편지를 받고 읽다가 조용히 방으로 들어갔다. 그리고 몇 시간 동안 안에서 우는 소리가 들렸다고 한다.","characters":["P-f310b84f8f20"]},{"id":"RP-0159481","time":"2026-05-18T22:51:00+09:00","room":"RP","name":"님드 알 쿠라이시","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f310b84f8f20"]},{"id":"RP-0159482","time":"2026-05-18T22:51:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
